import { BooleanColumn, StringColumn, TableNameColumn, FieldNameColumn, ScriptColumn, Table } from '../../db'

export const sys_script_client = Table({
    name: 'sys_script_client',
    extends: 'sys_metadata',
    schema: {
        name: StringColumn({ maxLength: 40 }),
        table: TableNameColumn({}),
        active: BooleanColumn({ default: true }),
        applies_extended: BooleanColumn({ default: false }),
        global: BooleanColumn({ default: true }),
        ui_type: StringColumn({
            choices: { 0: 'Desktop', 1: 'Mobile/Service Portal', 10: 'All' },
            default: 0,
        }),
        type: StringColumn({
            choices: {
                '': '--None--',
                onCellEdit: 'onCellEdit',
                onChange: 'onChange',
                onLoad: 'onLoad',
                onSubmit: 'onSubmit',
            },
            dropdown: 'dropdown_with_none',
        }),
        description: StringColumn({ maxLength: 4000 }),
        messages: StringColumn({ maxLength: 4000 }),
        script: ScriptColumn({}),
        isolate_script: BooleanColumn({ default: false }),
        view: StringColumn({ maxLength: 40 }),
        field: FieldNameColumn({
            dropdown: 'dropdown_with_none',
        }),
    },
})
